using System.Text;
using static WinSystemHelper.CommandUtilities;

namespace WinSystemHelper;

internal sealed class PendingUpdateStatus(
    ILogger<Worker> logger,
    ServiceFiles files,
    ServiceInstallation installation,
    QueueStore queueStore,
    RuntimeConfiguration runtime)
{
    public async Task SendPendingUpdateStatusAsync(CancellationToken cancellationToken)
    {
        string statusMarkerPath = installation.GetUpdateStatusMarkerPath();
        if (!File.Exists(statusMarkerPath))
        {
            // An updater generated by a pre-1.6 build reports to the old public folder.
            // That folder is writable by any local user, so its text is only relayed
            // (bounded and labelled) and never trusted for anything else.
            string legacyMarkerPath = Path.Combine(
                SharedPathProvider.LegacyPublicRoot, "Updates", ServiceConstants.UpdateStatusMarkerFileName);
            if (!File.Exists(legacyMarkerPath))
            {
                return;
            }

            try
            {
                string legacyStatus = await ServiceFiles.ReadUntrustedTextAsync(legacyMarkerPath, cancellationToken);
                if (!string.IsNullOrWhiteSpace(legacyStatus))
                {
                    await ImportLegacyNoticeAsync(
                        legacyMarkerPath,
                        "ℹ️ Status left by the previous version: " + TruncateForTelegram(legacyStatus, 500),
                        cancellationToken);
                }
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                logger.LogWarning(ex, "Failed to read the legacy update status marker.");
            }

            return;
        }

        try
        {
            string status = await File.ReadAllTextAsync(statusMarkerPath, Encoding.UTF8, cancellationToken);
            if (!string.IsNullOrWhiteSpace(status))
            {
                await ImportLegacyNoticeAsync(statusMarkerPath, status.Trim(), cancellationToken);
            }
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            throw;
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, "Failed to read or send pending OTA update status.");
        }
    }

    private async Task ImportLegacyNoticeAsync(string path, string text, CancellationToken token)
    {
        token.ThrowIfCancellationRequested();
        string identity = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(path + text)));
        foreach (long chat in runtime.GetAdminChatIdsSnapshot())
            await queueStore.EnqueueTextAsync(chat, text, dedupe: $"legacy:{identity}:{chat}");
        files.DeleteTempFile(path);
    }
}
